-- =============================================================================
-- HAND-WRITTEN: audit log is append-only
-- =============================================================================
-- A record of who touched what is worthless if it can be edited afterwards. Row
-- triggers reject UPDATE and DELETE; a statement trigger rejects TRUNCATE.
-- (DROP SCHEMA / DROP TABLE are DDL and are not blocked — those need schema
-- ownership, which the application's runtime role should NOT have in
-- production. See docs/PHASE1_NOTES.md.)

CREATE OR REPLACE FUNCTION nw_reject_audit_mutation() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'AuditLog is append-only (% rejected)', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "AuditLog_no_update_delete"
  BEFORE UPDATE OR DELETE ON "AuditLog"
  FOR EACH ROW EXECUTE FUNCTION nw_reject_audit_mutation();

CREATE TRIGGER "AuditLog_no_truncate"
  BEFORE TRUNCATE ON "AuditLog"
  FOR EACH STATEMENT EXECUTE FUNCTION nw_reject_audit_mutation();

-- =============================================================================
-- HAND-WRITTEN: an account must hold at least one role
-- =============================================================================
-- "At most one provider role" and "provider role requires a matching Staff
-- link" are enforced in application code, where the error can be explained.
ALTER TABLE "Account"
  ADD CONSTRAINT "Account_roles_nonempty" CHECK (cardinality("roles") > 0);

